-- Target: luby-music / afsowcntqlimbtyfnceu only. Additive setup; no registration data is changed.
BEGIN;
CREATE TABLE IF NOT EXISTS public.course_classes (
  id text PRIMARY KEY,
  data jsonb NOT NULL CHECK (jsonb_typeof(data) = 'object'),
  version bigint NOT NULL DEFAULT 1 CHECK (version > 0),
  updated_at timestamptz NOT NULL DEFAULT now()
);
ALTER TABLE public.course_classes ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.course_classes FROM PUBLIC, anon, authenticated;
GRANT SELECT, INSERT, UPDATE ON public.course_classes TO service_role;
CREATE TABLE IF NOT EXISTS public.course_classes_preview (
  id text PRIMARY KEY,
  data jsonb NOT NULL CHECK (jsonb_typeof(data) = 'object'),
  version bigint NOT NULL DEFAULT 1 CHECK (version > 0),
  updated_at timestamptz NOT NULL DEFAULT now()
);
ALTER TABLE public.course_classes_preview ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.course_classes_preview FROM PUBLIC, anon, authenticated;
GRANT SELECT, INSERT, UPDATE ON public.course_classes_preview TO service_role;
COMMIT;
